steps:
{
  "memory": {
    "mode": "lite",
    "path": "./.mono-agent/memory",
    "writeMode": "append-host-summary",
    "recallTool": {
      "enabled": true
    },
    "rememberTool": {
      "enabled": true
    }
  }
}

{
  "memory": {
    "mode": "lite",
    "path": "./.mono-agent/memory",
    "writeMode": "append-host-summary",
    "recallTool": {
      "enabled": true
    },
    "rememberTool": {
      "enabled": true
    }
  }
}

{
  "memory": {
    "mode": "journal",
    "path": "./.mono-agent/memory",
    "writeMode": "append-host-summary",
    "embeddings": {
      "provider": "ollama",
      "endpoint": "http://localhost:11434",
      "model": "nomic-embed-text:v1.5",
      "dim": 768
    },
    "recallTool": {
      "enabled": true
    },
    "rememberTool": {
      "enabled": true
    }
  }
}

{
  "memory": {
    "mode": "bujo",
    "path": "./.mono-agent/memory",
    "writeMode": "capture",
    "embeddings": {
      "provider": "ollama",
      "endpoint": "http://localhost:11434",
      "model": "nomic-embed-text:v1.5",
      "dim": 768
    },
    "llm": {
      "provider": "agent-host",
      "model": "openai-codex:gpt-5.6-terra"
    },
    "recallTool": {
      "enabled": true
    },
    "rememberTool": {
      "enabled": true
    }
  }
}

{
  "webhook": {
    "enabled": true
  }
}

{
  "telegram": {
    "enabled": true,
    "allowedChatIds": [
      "<TELEGRAM_CHAT_ID>"
    ]
  }
}

{
  "slack": {
    "enabled": true,
    "allowedChannelIds": [
      "<SLACK_CHANNEL_ID>"
    ]
  }
}

{
  "openaiApi": {
    "enabled": true
  }
}

{
  "cron": {
    "dir": "cron"
  }
}

{
  "sandbox": {
    "mode": "native",
    "network": {
      "mode": "localhost"
    },
    "readableRoots": [
      "."
    ],
    "writableRoots": [
      "."
    ],
    "fallback": "fail-closed"
  }
}
